      const originalCreds = {
        accessKeyId: "expiring",
        secretAccessKey: "secret",
        expiration: new Date(Date.now() + 2 * 60_000),
      };
      const provider = vi.fn().mockResolvedValueOnce(originalCreds).mockRejectedValueOnce(new Error("refresh failed"));
